    std::array<HWND,6> labels{};win::DesktopAppearance& appearance;DoorBulletinWindowPorts ports;
    std::optional<app::DoorBulletinCatalog> catalog;app::DoorBulletinId selected{};bool creating{},populating{},dirty{},uncertain{};
    std::unique_ptr<file_manager::PreviewWindow> viewer;
    Impl(HINSTANCE i,HWND o,win::DesktopAppearance& a,DoorBulletinWindowPorts p):instance(i),owner(o),appearance(a),ports(std::move(p)){}
    void feedback(std::wstring_view message){SetWindowTextW(status,std::wstring(message).c_str());UpdateWindow(status);}
    bool discard(){return !dirty||MessageBoxW(window,L"Discard the unsaved Door Bulletin edits?",L"Door Bulletins",MB_YESNO|MB_DEFBUTTON2|MB_ICONQUESTION)==IDYES;}
    const app::DoorBulletinEntry* entry()const{if(!catalog)return nullptr;const auto at=std::find_if(catalog->entries.begin(),catalog->entries.end(),[&](const auto& e){return e.definition.id==selected;});return at==catalog->entries.end()?nullptr:&*at;}
    void controls(){const bool ready=catalog.has_value()&&(creating||entry());const bool generated=ComboBox_GetCurSel(source)==1;
        for(const auto h:{title,enabled,source})EnableWindow(h,ready&&!uncertain);EnableWindow(number,ready&&creating&&!uncertain);
        for(const auto h:{door,path,format})EnableWindow(h,ready&&generated&&!uncertain);
        EnableWindow(list,!uncertain);EnableWindow(GetDlgItem(window,new_id),catalog.has_value()&&!uncertain);
        EnableWindow(save,ready&&!uncertain);EnableWindow(remove,ready&&!creating&&!uncertain);EnableWindow(validate,ready&&!creating&&!dirty&&!uncertain);EnableWindow(preview,ready&&!creating&&!dirty&&!uncertain);EnableWindow(plain,ready&&!creating&&!dirty&&!uncertain);
        const auto n=number?::sfx::config_ui::number(number):0;std::wstring message;
        if(generated)message=L"Relative to the Door's working folder. ASCII path: 240 characters total, 128 per name. Source files stay in place.";
        else message=L"Display files: DB"+(n>=1&&n<=999?std::to_wstring(1000+n).substr(1):std::wstring(L"001..999"))+L".ANS / .ASC, with exact security overrides. Enabled bulletins are visible to all callers.";
        SetWindowTextW(hint,message.c_str());
    }
    void fill_doors(app::DoorId current){ComboBox_ResetContent(door);bool found{};if(ports.doors)for(const auto& item:ports.doors()){const auto label=std::to_wstring(item.first)+L" - "+wide(item.second);const auto at=ComboBox_AddString(door,label.c_str());ComboBox_SetItemData(door,at,item.first);if(item.first==current){ComboBox_SetCurSel(door,at);found=true;}}
        if(current&&!found){const auto label=std::to_wstring(current)+L" - Door unavailable";const auto at=ComboBox_AddString(door,label.c_str());ComboBox_SetItemData(door,at,current);ComboBox_SetCurSel(door,at);}
    }
    void form(const app::DoorBulletinDefinition& d,bool is_new){if(viewer)viewer->close();populating=true;selected=d.id;creating=is_new;dirty=false;uncertain=false;SetWindowTextW(number,std::to_wstring(d.id.value).c_str());SetWindowTextW(title,wide(d.title).c_str());Button_SetCheck(enabled,d.enabled?BST_CHECKED:BST_UNCHECKED);ComboBox_SetCurSel(source,static_cast<int>(d.source));fill_doors(d.door);SetWindowTextW(path,wide(d.relative_path).c_str());ComboBox_SetCurSel(format,d.format==app::GraphicsMode::ansi?1:0);populating=false;controls();}
