DoorBulletinWindow::DoorBulletinWindow(HINSTANCE i,HWND owner,win::DesktopAppearance& appearance,DoorBulletinWindowPorts ports):impl_(std::make_unique<Impl>(i,owner,appearance,std::move(ports))){}
DoorBulletinWindow::~DoorBulletinWindow(){close();}
bool DoorBulletinWindow::show(){auto& p=*impl_;if(!p.window){p.viewer.reset();WNDCLASSEXW type{sizeof(type)};type.lpfnWndProc=Impl::proc;type.hInstance=p.instance;type.hCursor=LoadCursorW(nullptr,IDC_ARROW);type.lpszClassName=class_name;if(!GetClassInfoExW(p.instance,class_name,&type)){type=WNDCLASSEXW{sizeof(type)};type.lpfnWndProc=Impl::proc;type.hInstance=p.instance;type.hCursor=LoadCursorW(nullptr,IDC_ARROW);type.lpszClassName=class_name;if(!RegisterClassExW(&type))return false;}MONITORINFO monitor{sizeof(monitor)};if(!GetMonitorInfoW(MonitorFromWindow(p.owner,MONITOR_DEFAULTTONEAREST),&monitor)&&!SystemParametersInfoW(SPI_GETWORKAREA,0,&monitor.rcWork,0))return false;const int work_width=monitor.rcWork.right-monitor.rcWork.left,work_height=monitor.rcWork.bottom-monitor.rcWork.top;const int width=std::min(1080,std::max(800,work_width-24)),height=std::min(820,std::max(700,work_height-16));if(!CreateWindowExW(WS_EX_CONTROLPARENT,class_name,L"Doors > Door Bulletins",WS_OVERLAPPEDWINDOW|WS_CLIPCHILDREN,monitor.rcWork.left+(work_width-width)/2,monitor.rcWork.top+(work_height-height)/2,width,height,p.owner,nullptr,p.instance,&p))return false;}ShowWindow(p.window,SW_SHOWNORMAL);SetForegroundWindow(p.window);return true;}
bool DoorBulletinWindow::translate(MSG& message){auto& p=*impl_;if(p.viewer&&p.viewer->translate(message))return true;return p.window&&(message.hwnd==p.window||IsChild(p.window,message.hwnd))&&IsDialogMessageW(p.window,&message)!=FALSE;}
bool DoorBulletinWindow::confirm_close(){return !impl_->window||impl_->discard();}
void DoorBulletinWindow::close(){if(impl_->viewer)impl_->viewer->close();if(impl_->window)DestroyWindow(impl_->window);}
